// Normalise ONE Alertmanager webhook (v4) call into ONE runner request {agent, event} (CONTRACT.md §1).
// One run per alert GROUP, never per alert. Returns NO items (= the execution ends quietly) when the
// group is resolved or is only noise. Everything from the payload is DATA: it only ever lands inside
// event.data / event.subject (a JSON POST body) and, via Claim, a bound $1::jsonb — never a URL or SQL text.
const AGENT = 'ops-investigator';
const NOISE = ['Watchdog', 'InfoInhibitor', 'KubeMemoryOvercommit'];
const COOLDOWN_HOURS = 6;          // Claim skips a group launched within this window (Alertmanager repeat is 12h)
const MAX_ALERTS = 10;             // alerts carried in event.data; the rest are counted in alerts_total
const MAX_EVENT_BYTES = 24 * 1024; // contract caps are 32 KiB (body) / 64 KiB (event); stay well under
const MAX_KEYS = 40;               // labels/annotations per map
const MAX_SUBJECT = 200;

const item = $input.first().json || {};
const p = (item.body && typeof item.body === 'object') ? item.body : item;   // webhook item, or a bare payload in tests

if (p.status !== 'firing') return [];
const all = (Array.isArray(p.alerts) ? p.alerts : []).filter(a => a && typeof a === 'object' && (a.status === undefined || a.status === 'firing'));
// Alertmanager's max_alerts drops alerts from the payload and counts them in truncatedAlerts.
const dropped = Number.isInteger(p.truncatedAlerts) && p.truncatedAlerts > 0 ? p.truncatedAlerts : 0;
const total = all.length + dropped;
const nameOf = a => String((a.labels && a.labels.alertname) || '');
if (!all.length || all.every(a => NOISE.includes(nameOf(a)))) return [];

const obj = v => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
let cut = false;                   // set by clip(): something was shortened
const clip = (v, n) => { const s = typeof v === 'string' ? v : (v === undefined || v === null ? '' : String(v)); if (s.length <= n) return s; cut = true; return s.slice(0, n) + '…[truncated]'; };
const clipMap = (m, n) => {
  const out = {};
  for (const k of Object.keys(obj(m)).sort().slice(0, MAX_KEYS)) out[clip(k, 128)] = clip(m[k], n);
  return out;
};
const line = s => String(s).replace(/[\u0000-\u001f\u007f]+/g, ' ').trim();

const groupLabels = obj(p.groupLabels), commonLabels = obj(p.commonLabels);
const alertname = line(commonLabels.alertname || groupLabels.alertname || nameOf(all.find(a => !NOISE.includes(nameOf(a))) || all[0]) || 'unknown').slice(0, 120) || 'unknown';
const namespace = line(commonLabels.namespace || groupLabels.namespace || '').slice(0, 63) || '-';
const subject = `${alertname}/${namespace}`.slice(0, MAX_SUBJECT);

// --- stable dedupe key: SHA-256 of groupKey (the Code sandbox has no `crypto`, so a small pure-JS one).
function sha256hex(str) {
  const b = [];                                  // UTF-8 encode
  for (const ch of str) {
    let c = ch.codePointAt(0);
    if (c < 0x80) b.push(c);
    else if (c < 0x800) b.push(0xc0 | c >> 6, 0x80 | c & 63);
    else if (c < 0x10000) b.push(0xe0 | c >> 12, 0x80 | c >> 6 & 63, 0x80 | c & 63);
    else b.push(0xf0 | c >> 18, 0x80 | c >> 12 & 63, 0x80 | c >> 6 & 63, 0x80 | c & 63);
  }
  const K = [];
  for (let n = 2, found = 0; found < 64; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break; }
    if (prime) { K.push((Math.pow(n, 1 / 3) % 1) * 4294967296 >>> 0); found++; }
  }
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bitLen = b.length * 8;
  b.push(0x80);
  while (b.length % 64 !== 56) b.push(0);
  for (let i = 7; i >= 0; i--) b.push(i >= 4 ? 0 : (bitLen >>> (i * 8)) & 255);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < b.length; o += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = (b[o + 4 * i] << 24 | b[o + 4 * i + 1] << 16 | b[o + 4 * i + 2] << 8 | b[o + 4 * i + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, bb, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = bb; bb = a; a = (t1 + t2) >>> 0;
    }
    const v = [a, bb, c, d, e, f, g, h];
    for (let i = 0; i < 8; i++) H[i] = (H[i] + v[i]) >>> 0;
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}
// groupKey is Alertmanager's own stable id for the group; fall back to receiver + sorted groupLabels.
const groupKey = typeof p.groupKey === 'string' && p.groupKey
  ? p.groupKey
  : `${p.receiver || ''}:${JSON.stringify(Object.keys(groupLabels).sort().map(k => [k, groupLabels[k]]))}`;
const dedupe_key = 'alertmanager:' + sha256hex(groupKey);

// --- event id: fresh ULID-shaped id per launch (as in agent-build-event.js). The runner dedupes on
// (event.id, agent) forever, so a deterministic id would block the next legitimate run after the cooldown.
const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let t = Date.now(), time = '';
for (let i = 0; i < 10; i++) { time = B32[t % 32] + time; t = Math.floor(t / 32); }
let rand = '';
for (let i = 0; i < 16; i++) rand += B32[Math.floor(Math.random() * 32)];
const id = time + rand;

// --- data, shrunk until the whole event fits MAX_EVENT_BYTES (UTF-8).
const utf8 = s => { let n = 0; for (const ch of s) { const c = ch.codePointAt(0); n += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4; } return n; };
const build = (nAlerts, labelLen, annLen) => {
  cut = false;
  const data = {
    common_labels: clipMap(commonLabels, labelLen),
    common_annotations: clipMap(p.commonAnnotations, annLen),
    alerts: all.slice(0, nAlerts).map(a => ({
      labels: clipMap(a.labels, labelLen),
      annotations: clipMap(a.annotations, annLen),
      startsAt: clip(a.startsAt, 64),
      generatorURL: clip(a.generatorURL, 512),
    })),
  };
  if (cut || nAlerts < total) { data.alerts_total = total; data.truncated = true; }
  return { id, type: 'alert.firing', source: 'alertmanager', subject, dedupe_key, trust: 'internal', data };
};
let nAlerts = Math.min(all.length, MAX_ALERTS), labelLen = 256, annLen = 2000;
let event = build(nAlerts, labelLen, annLen);
while (utf8(JSON.stringify(event)) > MAX_EVENT_BYTES) {
  if (annLen > 200) annLen = Math.floor(annLen / 2);
  else if (nAlerts > 1) nAlerts--;
  else if (labelLen > 64) labelLen = Math.floor(labelLen / 2);
  else if (annLen > 20) annLen = Math.floor(annLen / 2);
  else break;                                    // absurd payload; the runner's own 422 is the backstop
  event = build(nAlerts, labelLen, annLen);
}

return [{ json: { agent: AGENT, event, alertname, alerts_total: total, cooldown_hours: COOLDOWN_HOURS } }];

// Derive an IN-CLUSTER resume URL for the "Wait for Result" node and attach it as `callback`.
//
// $execution.resumeUrl is "<WEBHOOK_URL>webhook-waiting/<executionId>?signature=<resumeToken>".
// WEBHOOK_URL is the PUBLIC tunnel host, which only passes ^/webhook/inbound-mail.* — so we
// keep n8n's path + query (the signature IS the per-execution auth; n8n 2.x rejects a resume
// without it: 401 {"error":"Invalid token"}) and swap the origin for the webhook tier's
// in-cluster Service. Both the main and the webhook process serve /webhook-waiting/*
// (N8N_DISABLE_PRODUCTION_MAIN_PROCESS is unset); waiting executions are looked up in
// Postgres by id, so no activation/registration is involved and no webhook-tier roll is needed.
const CALLBACK_ORIGIN = 'http://n8n-webhook.n8n.svc.cluster.local:5678';

const resumeUrl = String($execution.resumeUrl || '');
const m = resumeUrl.match(/^https?:\/\/[^/]+(\/.*)$/);
if (!m) throw new Error(`Unexpected $execution.resumeUrl shape: "${resumeUrl}"`);
const pathAndQuery = m[1];

// Fail now, not 30 minutes from now: the URL must be /webhook-waiting/<this execution>?…signature=…
const shape = pathAndQuery.match(/^\/webhook-waiting\/([^/?#]+)\?(?:[^#]*&)?signature=[^&#]+/);
if (!shape) {
  throw new Error('resumeUrl is not "/webhook-waiting/<id>?signature=<token>" at the root of WEBHOOK_URL — '
    + 'n8n changed its resume-URL shape or WEBHOOK_URL gained a path; see docs/agent-sandbox-n8n.md');
}
if (String(shape[1]) !== String($execution.id)) {
  throw new Error(`resumeUrl execution id ${shape[1]} != $execution.id ${$execution.id}`);
}

const item = $input.first().json;
return [{ json: { ...item, callback: CALLBACK_ORIGIN + pathAndQuery } }];

// Normalise a runner callback (CONTRACT.md §3) into one agent_runs ledger row.
// Shared by agent-run-manual.json (input = the Wait node's webhook item) and agent-result.json
// (input = the Webhook item, possibly via Ensure Table). Everything in the body is DATA: it is
// clipped, type-checked, and later bound as ONE jsonb parameter — never concatenated into SQL.
const OUTCOMES = ['done', 'nothing_to_do', 'needs_human', 'failed'];
const EXIT_REASONS = ['completed', 'deadline', 'job_failed', 'no_result', 'invalid_result'];

let body = ($input.first().json || {}).body;
if (!body || typeof body !== 'object') {
  try { body = $('Result Webhook').first().json.body; } catch (e) { /* not the agent-result workflow */ }
}
if (!body || typeof body !== 'object') throw new Error('Callback has no JSON body');

const str = (v, n) => (typeof v === 'string' ? v : (v === undefined || v === null ? '' : String(v))).slice(0, n);
const ts = (v) => {
  if (v === undefined || v === null || v === '') return null;
  let d;
  if (typeof v === 'number') d = new Date(v < 1e12 ? v * 1000 : v);   // epoch seconds or ms
  else d = new Date(String(v));
  return isNaN(d.getTime()) ? null : d.toISOString();
};

const run_id = str(body.run_id, 128).trim();
if (!/^[A-Za-z0-9._:-]{1,128}$/.test(run_id)) throw new Error('Callback run_id missing or malformed');

const result = (body.result && typeof body.result === 'object') ? body.result : {};
const exit_reason = EXIT_REASONS.includes(body.exit_reason) ? body.exit_reason : str(body.exit_reason || 'unknown', 64);
const outcome = OUTCOMES.includes(result.outcome) ? result.outcome : 'failed';
const outputs = (Array.isArray(result.outputs) ? result.outputs : [])
  .filter(o => o && typeof o === 'object')
  .slice(0, 20)
  .map(o => ({ kind: str(o.kind, 64), title: str(o.title, 300), body: str(o.body, 32768) }));

// event type/subject are not in the callback; take them from this execution's Build Event when
// it exists (manual/Wait flow), else from body.event if the runner ever includes it, else null.
let ev = null;
try { ev = $('Build Event').first().json.event; } catch (e) { ev = (body.event && typeof body.event === 'object') ? body.event : null; }

return [{ json: {
  run_id,
  agent: str(body.agent, 64),
  event_id: str(body.event_id || (ev && ev.id), 128) || null,
  event_type: ev ? str(ev.type, 128) : null,
  subject: ev ? str(ev.subject, 200) : null,
  started: ts(body.started),
  finished: ts(body.finished),
  exit_reason,
  outcome,
  summary: str(result.summary, 2048),
  outputs,
} }];

// agent-alert.json's copy of agent-timeout-row.js (kept separate so the live agent-run-manual.json, whose Wait is
// still 30 minutes, needs no re-import). The Wait node resumed on its 75-minute limit, not on a callback.
// 75 covers the worst case: RUNNER_MAX_QUEUE_WAIT (45m) + the agent's timeout (15m) + the runner's 5m deadline
// grace = 65m, plus ~10m for polling and callback retries. A run that queued and then ran its full deadline still
// calls back first; a queue_expired run calls back at 45m. The Wait's output is then its INPUT (the runner's 202
// response), so we still know run_id. Record the give-up in the ledger so the
// run is visible; a late callback can no longer resume this execution (n8n answers 409), but the
// runner keeps its own record: GET /runs/<run_id>.
const r = $input.first().json || {};
const launched = (r.body && typeof r.body === 'object') ? r.body : {};
let ev = {}, agent = '';
try { const b = $('Build Event').first().json; ev = b.event || {}; agent = b.agent || ''; } catch (e) {}

const run_id = String(launched.run_id || '').slice(0, 128);
if (!run_id) throw new Error('Timed out, and the launch response had no run_id');

return [{ json: {
  run_id,
  agent,
  event_id: ev.id || null,
  event_type: ev.type || null,
  subject: ev.subject || null,
  started: null,
  finished: new Date().toISOString(),
  exit_reason: 'callback_timeout',
  outcome: 'failed',
  summary: 'No callback from agent-runner within 75 minutes. Check GET /runs/' + run_id
    + ' on the runner and the Job run-' + run_id + ' in namespace agents.',
  outputs: [],
} }];

// Build the ntfy push from the ledger row that was just written (Insert Ledger ... RETURNING).
// No row = duplicate callback (ON CONFLICT DO NOTHING) = no push.
// The push carries outcome + summary + report TITLE only; the report body stays in agent_runs.outputs.
const EMOJI = { done: 'white_check_mark', nothing_to_do: 'zzz', needs_human: 'raising_hand', failed: 'warning' };
const PRIO = { done: '3', nothing_to_do: '2', needs_human: '4', failed: '4' };

// Header values must be single-line ASCII; the full text goes in the body.
const header = (s, n) => String(s || '').replace(/[^\x20-\x7E]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.run_id) continue;
  let outputs = r.outputs;
  if (typeof outputs === 'string') { try { outputs = JSON.parse(outputs); } catch (e) { outputs = []; } }
  const report = (Array.isArray(outputs) ? outputs : []).find(o => o && o.kind === 'report');
  const reportTitle = report ? String(report.title || '') : '';
  const outcome = String(r.outcome || 'failed');

  const lines = [String(r.summary || '(no summary)').slice(0, 3000)];
  if (reportTitle) lines.push(`Report: ${reportTitle.slice(0, 300)}`);
  lines.push(`run ${r.run_id} · ${r.exit_reason || '?'}`);

  out.push({ json: {
    title: header(`${r.agent || 'agent'}: ${outcome}${reportTitle ? ' - ' + reportTitle : ''}`, 120),
    message: lines.join('\n'),
    tags: EMOJI[outcome] || 'robot',
    priority: PRIO[outcome] || '3',
  } });
}
return out;

// Re-title the shared Format Push output (agent-format-push.js) for an alert-started run, so the push says it
// was AUTOMATIC and names the alert: "ops-investigator: <outcome> - <alertname>". The report title moves to the
// body (Format Push already puts "Report: <title>" there). No input items (duplicate callback) = no push.
// exit_reason queue_expired (the runner's queue was busy and the run never started) is not a failure of the
// agent: it gets a quiet, low-priority "not investigated" push instead of Format Push's priority-4 warning.
const header = (s, n) => String(s || '').replace(/[^\x20-\x7E]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

let b = {}, row = {};
try { b = $('Build Event').first().json || {}; } catch (e) {}
try { row = $('Insert Ledger').first().json || {}; } catch (e) {}
const ev = b.event || {};
const alertname = b.alertname || String(ev.subject || 'alert').split('/')[0];
const n = Number(b.alerts_total) || 0;

return $input.all().map(it => {
  const j = it.json || {};
  if (row.exit_reason === 'queue_expired') {
    return { json: {
      ...j,
      title: header(`${row.agent || b.agent || 'agent'}: not investigated (queue busy) - ${alertname}`, 120),
      message: `Not investigated: other alert runs held every agent slot and this one expired in the runner's queue.\n`
        + `Alertmanager will re-send the group if it is still firing after its repeat interval.\n`
        + `Auto-started by Alertmanager: ${ev.subject || alertname}${n ? ` (${n} alert${n === 1 ? '' : 's'})` : ''}\n`
        + `run ${String(row.run_id || '?').slice(0, 128)} · queue_expired`,
      tags: 'hourglass,rotating_light',
      priority: '2',
    } };
  }
  return { json: {
    ...j,
    title: header(`${row.agent || b.agent || 'agent'}: ${row.outcome || 'failed'} - ${alertname}`, 120),
    message: `Auto-started by Alertmanager: ${ev.subject || alertname}${n ? ` (${n} alert${n === 1 ? '' : 's'})` : ''}\n` + String(j.message || ''),
    tags: [j.tags, 'rotating_light'].filter(Boolean).join(','),
  } };
});

// The runner did not start the run (non-202, or unreachable via the HTTP node's error output). Turn that into
// ONE agent_runs ledger row so the refusal is visible, instead of retrying: Alertmanager re-sends anyway and the
// Claim cooldown already holds this group for its window. exit_reason names the refusal KIND
// (refused_429, refused_queue_full, refused_503, …, runner_unreachable); Insert Refusal counts earlier rows of the
// same kind so Refusal Push sends at most one quiet push per kind per window. A 429 whose body is
// {"error":"queue_full"} (runner 0.2.0+: every agent slot busy AND the wait queue full) is its own kind, so a
// burst-time queue_full does not silence the push for a later daily-cap 429 in the same window.
const r = $input.first().json || {};
let agent = '', ev = {};
try { const b = $('Build Event').first().json; agent = b.agent || ''; ev = b.event || {}; } catch (e) {}

const code = Number(r.statusCode || 0);
const body = (r.body && typeof r.body === 'object') ? r.body : {};
const detail = String(typeof r.body === 'string' ? r.body : (body.error || body.detail || body.message || '')).slice(0, 300);
const WHY = {
  200: 'this event id was already launched earlier (unexpected: alert event ids are fresh per launch)',
  401: 'runner rejected the bearer token (check the agent-runner credential)',
  404: 'runner does not know this agent (is the ops-investigator manifest deployed?)',
  422: 'runner rejected the manifest, event, or callback URL',
  429: 'daily run cap or cluster quota reached',
  queue_full: 'runner queue is full (every agent slot busy and the wait queue at its limit) - alert not investigated',
  502: 'runner hit a Kubernetes error launching the Job',
  503: 'runner is paused (RUNNER_PAUSED=true)',
};

let exit_reason, summary;
if (r.error) {
  const e = typeof r.error === 'object' ? (r.error.message || JSON.stringify(r.error)) : String(r.error);
  exit_reason = 'runner_unreachable';
  summary = `Not started: could not reach agent-runner: ${String(e).slice(0, 300)}`;
} else if (code === 429 && body.error === 'queue_full') {
  exit_reason = 'refused_queue_full';
  summary = `Not started (HTTP 429): ${WHY.queue_full}${body.detail ? ` - ${String(body.detail).slice(0, 300)}` : ''}`;
} else {
  exit_reason = `refused_${code || 'unknown'}`;
  summary = `Not started (HTTP ${code || '?'}): ${WHY[code] || 'unexpected runner response'}${detail ? ` - ${detail}` : ''}`;
}

return [{ json: {
  run_id: `nolaunch-${String(ev.id || Date.now())}`.slice(0, 128),
  agent,
  event_id: ev.id || null,
  event_type: ev.type || null,
  subject: ev.subject || null,
  started: null,
  finished: new Date().toISOString(),
  exit_reason,
  outcome: 'failed',
  summary: summary.slice(0, 2048),
  outputs: [],
} }];

// At most ONE quiet push per refusal kind per window: Insert Refusal returns prior_same = the number of earlier
// agent_runs rows with the same exit_reason and event_type inside the window. Anything but 0 = stay silent
// (the ledger row is the record). No input row (ON CONFLICT) = silent too.
const header = (s, n) => String(s || '').replace(/[^\x20-\x7E]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.run_id || Number(r.prior_same) !== 0) continue;
  out.push({ json: {
    title: header(`${r.agent || 'agent'}: not started - ${String(r.subject || 'alert').split('/')[0]}`, 120),
    message: `${String(r.summary || '').slice(0, 1000)}\nFurther ${r.exit_reason} refusals for alert runs are recorded in agent_runs without a push for the next 6 hours.\n${r.run_id}`,
    tags: 'rotating_light,no_entry',
    priority: '2',
  } });
}
return out;
